import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.DnrXFDHb.js";const c=JSON.parse('{"title":"Flag Lifecycle & Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/flags-workflow.md","filePath":"en/guide/flags-workflow.md"}'),n={name:"en/guide/flags-workflow.md"};function l(r,e,o,d,h,g){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="flag-lifecycle-workflow" tabindex="-1">Flag Lifecycle &amp; Workflow <a class="header-anchor" href="#flag-lifecycle-workflow" aria-label="Permalink to &quot;Flag Lifecycle &amp; Workflow&quot;">​</a></h1><p>The feature flag lifecycle in можно spans six stages: <strong>Draft → Active → Paused → Archived → Deleted</strong>. This document covers the complete workflow, from creating your first flag to managing flags in a team environment.</p><h2 id="flag-lifecycle-states" tabindex="-1">Flag Lifecycle States <a class="header-anchor" href="#flag-lifecycle-states" aria-label="Permalink to &quot;Flag Lifecycle States&quot;">​</a></h2><pre class="mermaid">stateDiagram-v2
    [*] --&gt; Draft : Create flag
    Draft --&gt; Active : Enable
    Active --&gt; Paused : Temporarily disable
    Paused --&gt; Active : Resume
    Active --&gt; Archived : Archive
    Paused --&gt; Archived : Archive
    Archived --&gt; Active : Restore
    Archived --&gt; [*] : Delete permanently
    Draft --&gt; [*] : Delete
</pre><table tabindex="0"><thead><tr><th>State</th><th>Description</th></tr></thead><tbody><tr><td><strong>Draft</strong></td><td>Flag created but not evaluating in SDKs. Ideal for setup before launch.</td></tr><tr><td><strong>Active</strong></td><td>Flag is live. SDKs evaluate rules and return values.</td></tr><tr><td><strong>Paused</strong></td><td>Flag temporarily disabled. SDKs return the default value for all contexts.</td></tr><tr><td><strong>Archived</strong></td><td>Flag removed from active evaluation. Retained for audit and historical reference.</td></tr><tr><td><strong>Deleted</strong></td><td>Flag permanently removed from the system. Irreversible.</td></tr></tbody></table><h2 id="creating-a-flag" tabindex="-1">Creating a Flag <a class="header-anchor" href="#creating-a-flag" aria-label="Permalink to &quot;Creating a Flag&quot;">​</a></h2><p>Navigate to the <strong>Flags</strong> page and click <strong>New Flag</strong>. Fill in the required fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Key</strong></td><td>Yes</td><td>Unique identifier, immutable after creation. Use <code>snake_case</code> (e.g., <code>dark_mode_v2</code>).</td></tr><tr><td><strong>Name</strong></td><td>Yes</td><td>Human-readable label shown in the dashboard.</td></tr><tr><td><strong>Description</strong></td><td>No</td><td>Details about the flag&#39;s purpose and expected behaviour.</td></tr><tr><td><strong>Type</strong></td><td>Yes</td><td><code>boolean</code> (on/off) or <code>string</code> (multi-value).</td></tr><tr><td><strong>Default value</strong></td><td>Yes</td><td>The value returned when no targeting rules match or the flag is paused. For booleans: <code>true</code> or <code>false</code>.</td></tr><tr><td><strong>Tags</strong></td><td>No</td><td>Comma-separated labels for organization and filtering.</td></tr></tbody></table><p>After creation the flag is in <strong>Draft</strong> state. Configure targeting rules and rollouts before enabling it.</p><blockquote><p><strong>Tip:</strong> Keep flag keys descriptive and scoped to their domain. Prefer <code>checkout_redesign</code> over <code>flag_42</code>.</p></blockquote><h2 id="editing-a-flag" tabindex="-1">Editing a Flag <a class="header-anchor" href="#editing-a-flag" aria-label="Permalink to &quot;Editing a Flag&quot;">​</a></h2><p>All fields except the <strong>key</strong> can be modified at any stage. Changes are recorded in the <a href="./audit.html">audit log</a> with full diff details.</p><p>Common edits include:</p><ul><li>Adjusting targeting rules</li><li>Changing the percentage rollout</li><li>Updating the description</li><li>Adding or removing tags</li><li>Modifying the default value</li></ul><blockquote><p><strong>Warning:</strong> Changing a boolean flag&#39;s type to string (or vice versa) invalidates existing evaluation results. Plan this change carefully and coordinate with consuming services.</p></blockquote><h2 id="toggling-a-flag" tabindex="-1">Toggling a Flag <a class="header-anchor" href="#toggling-a-flag" aria-label="Permalink to &quot;Toggling a Flag&quot;">​</a></h2><p>Toggling means switching a flag between <strong>Active</strong> and <strong>Paused</strong>, or changing its default value to rapidly gate a feature.</p><h3 id="from-the-dashboard" tabindex="-1">From the Dashboard <a class="header-anchor" href="#from-the-dashboard" aria-label="Permalink to &quot;From the Dashboard&quot;">​</a></h3><ol><li>Go to the flag detail page.</li><li>Click <strong>Pause</strong> to immediately stop evaluation (returns default value).</li><li>Click <strong>Resume</strong> to re-enable evaluation.</li></ol><h3 id="using-the-rest-api" tabindex="-1">Using the REST API <a class="header-anchor" href="#using-the-rest-api" aria-label="Permalink to &quot;Using the REST API&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pause a flag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://your-instance/api/flags/checkout_redesign</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$JWT_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;state&quot;: &quot;PAUSED&quot;}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Resume a flag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://your-instance/api/flags/checkout_redesign</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$JWT_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;state&quot;: &quot;ACTIVE&quot;}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><blockquote><p><strong>Tip:</strong> Use the <code>PATCH</code> endpoint for quick state changes without re-applying all targeting rules.</p></blockquote><h2 id="archiving-a-flag" tabindex="-1">Archiving a Flag <a class="header-anchor" href="#archiving-a-flag" aria-label="Permalink to &quot;Archiving a Flag&quot;">​</a></h2><p>Archive a flag when the feature is fully rolled out and the flag is no longer needed for control. Archived flags:</p><ul><li>Stop being evaluated by SDKs (default value is returned).</li><li>Remain visible in the dashboard for historical reference.</li><li>Retain their full audit history.</li><li>Can be restored to <strong>Active</strong> if needed.</li></ul><p><strong>When to archive:</strong> The feature has been stable in production for a release cycle and no rollback is anticipated.</p><p><strong>When NOT to archive yet:</strong> The flag is temporary but the feature is still being rolled out or monitored.</p><h2 id="deleting-a-flag" tabindex="-1">Deleting a Flag <a class="header-anchor" href="#deleting-a-flag" aria-label="Permalink to &quot;Deleting a Flag&quot;">​</a></h2><p>Deletion is <strong>permanent and irreversible</strong>. Before deleting, consider archiving instead.</p><p><strong>When to delete:</strong></p><ul><li>The flag was a short-lived experiment and all related code has been removed.</li><li>The flag key is no longer referenced in any codebase.</li><li>The flag was created in error.</li></ul><blockquote><p><strong>Warning:</strong> Deleting a flag that is still referenced in application code will cause SDK evaluation errors. Always remove flag references from code before deletion.</p></blockquote><h2 id="organizing-flags-with-tags" tabindex="-1">Organizing Flags with Tags <a class="header-anchor" href="#organizing-flags-with-tags" aria-label="Permalink to &quot;Organizing Flags with Tags&quot;">​</a></h2><p>Tags are free-form labels you attach to flags for filtering and grouping.</p><p><strong>Recommended tagging strategy:</strong></p><table tabindex="0"><thead><tr><th>Tag</th><th>Purpose</th><th>Example</th></tr></thead><tbody><tr><td><code>team:payments</code></td><td>Owning team</td><td><code>team:platform</code></td></tr><tr><td><code>env:staging</code></td><td>Deployment environment</td><td><code>env:production</code></td></tr><tr><td><code>type:experiment</code></td><td>Flag category</td><td><code>type:kill-switch</code></td></tr><tr><td><code>service:checkout</code></td><td>Owning service</td><td><code>service:api-gateway</code></td></tr></tbody></table><p>Use the dashboard filter bar or API query parameters to find flags by tag:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://your-instance/api/flags?tags=team:payments,type:experiment</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$JWT_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="flag-dependencies" tabindex="-1">Flag Dependencies <a class="header-anchor" href="#flag-dependencies" aria-label="Permalink to &quot;Flag Dependencies&quot;">​</a></h2><p>можно does not enforce formal flag dependencies, but you can model them by chaining targeting rules or coordinating rollout strategies.</p><h3 id="explicit-dependency-via-segments" tabindex="-1">Explicit Dependency via Segments <a class="header-anchor" href="#explicit-dependency-via-segments" aria-label="Permalink to &quot;Explicit Dependency via Segments&quot;">​</a></h3><p>Create a <strong>segment</strong> representing the parent flag&#39;s target audience, then reference that segment in the child flag&#39;s targeting rules:</p><ol><li>Create a segment <code>checkout_v2_users</code> targeted by the parent flag.</li><li>In the child flag <code>checkout_v2_promo</code>, add a targeting rule that includes the segment <code>checkout_v2_users</code>.</li></ol><p>This ensures the child flag only evaluates for users who have the parent flag enabled. See <a href="./targeting.html">Targeting</a> for segment configuration.</p><h3 id="implicit-dependency-via-application-code" tabindex="-1">Implicit Dependency via Application Code <a class="header-anchor" href="#implicit-dependency-via-application-code" aria-label="Permalink to &quot;Implicit Dependency via Application Code&quot;">​</a></h3><p>Handle dependencies in your application:</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isFlagEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;checkout_v2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, context)) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> showPromo </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isFlagEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;checkout_v2_promo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, context);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p><strong>Tip:</strong> Document flag dependencies in the flag description field so the team understands the relationship at a glance.</p></blockquote><h2 id="team-workflow-best-practices" tabindex="-1">Team Workflow Best Practices <a class="header-anchor" href="#team-workflow-best-practices" aria-label="Permalink to &quot;Team Workflow Best Practices&quot;">​</a></h2><h3 id="pull-request-flow" tabindex="-1">Pull Request Flow <a class="header-anchor" href="#pull-request-flow" aria-label="Permalink to &quot;Pull Request Flow&quot;">​</a></h3><pre class="mermaid">graph LR
    A[Create draft flag in UI] --&gt; B[Write code behind flag]
    B --&gt; C[Open PR]
    C --&gt; D[Review targeting rules]
    D --&gt; E[Merge PR]
    E --&gt; F[Enable flag in staging]
    F --&gt; G[Verify in staging]
    G --&gt; H[Enable flag in production]
</pre><ol><li><strong>Create the flag as Draft</strong> before writing code. Configure targeting rules but leave it disabled.</li><li><strong>Write the guarded code</strong> in a feature branch. Use the flag key in your application.</li><li><strong>Review</strong> both the code and the flag configuration in the PR. Reference the flag key in the PR description.</li><li><strong>Enable the flag in staging</strong> after merge. Verify behaviour.</li><li><strong>Enable the flag in production</strong> with a conservative rollout (see <a href="./rollout.html">Rollout</a>).</li></ol><h3 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h3><ul><li>Assign a <strong>flag owner</strong> using a tag (e.g., <code>owner:alice</code>).</li><li>The owner is responsible for the flag&#39;s lifecycle: creation, rollout, and eventual removal.</li><li>Review owned flags weekly to identify candidates for archiving.</li></ul><h3 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h3><ul><li>Announce new flags in your team&#39;s communication channel.</li><li>Include the flag key, purpose, default value, and expected lifetime.</li><li>Notify the team before pausing or archiving a flag that other services may depend on.</li></ul><h3 id="environment-separation" tabindex="-1">Environment Separation <a class="header-anchor" href="#environment-separation" aria-label="Permalink to &quot;Environment Separation&quot;">​</a></h3><p>Use separate API keys per environment (staging, production) and tag flags accordingly. This prevents accidental cross-environment toggling.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Configure <a href="./targeting.html">Targeting Rules</a> to control who sees each flag value.</li><li>Set up a <a href="./rollout.html">Gradual Rollout</a> to safely release features.</li><li>Review the <a href="./audit.html">Audit Log</a> to track every change.</li></ul>`,60)])])}const u=a(n,[["render",l]]);export{c as __pageData,u as default};
